import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from 'src/app/services/auth.service';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent {


  products: Product[] = [];
  allProducts: Product[] = [];
  searchText: string = '';

  constructor(
    private fb: FormBuilder,
    private router: Router,
    private authService: AuthService,
    private ProductService: ProductService,

  ) {}

  ngOnInit(): void {
    this.loadProducts();
  }

  loadProducts(): void {
    console.log('Products:', this.products);

    this.ProductService.listAllProducts().subscribe((response: Product[]) => {
      this.products = response;
      this.allProducts = response;
    });
  }

  onSearch(): void {
    if (!this.searchText) {
      this.products = this.allProducts;
    } else {
      this.products = this.allProducts.filter(product =>
        product.title.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  onFiltersChanged(filters: any): void {
    if (!filters.searchText) {
      this.products = this.allProducts;
    } else {
      this.products = this.allProducts.filter(product =>
        product.title.toLowerCase().includes(filters.searchText.toLowerCase())
      );
    }
  }

  viewDetailsEvent(productID:Number){

  this.router.navigate(['products',productID]);
  // this.activatedRoute.params.subscribe(params => {
  //     this.productId = params['id'];
  //   });
  }
}
// this.productService.listAllproducts().subscribe((a)=>{console.log(a)})
